#!/bin/sh
# Upload the app to the VPS and (re)start it. Usage: deploy/deploy.sh (HOST=root@other.host deploy/deploy.sh for another server)
set -eu
HOST=${HOST:-root@45.76.106.71}
DIR=/opt/pump-graduated
cd "$(dirname "$0")/.."
ssh "$HOST" "id pumpgrad >/dev/null 2>&1 || useradd --system --no-create-home --shell /usr/sbin/nologin pumpgrad; mkdir -p $DIR/data/settings $DIR/data/jobs && chown pumpgrad: $DIR/data $DIR/data/settings $DIR/data/jobs && chmod 750 $DIR/data/settings; T=$DIR/data/settings/admin_token; [ -s \$T ] || { openssl rand -hex 12 > \$T; chown pumpgrad: \$T; chmod 600 \$T; }"
scp -q app/pumpapi.py app/recorder.py app/first_trades.py app/holders.py app/watch.py app/notify.py app/trader.py app/analyze.py app/rules.py app/wallets.py app/diprule.py app/dipwatch.py app/patterns.py app/monitor.py app/jobs.py app/coins.py app/traders.py app/wallet_review.py app/solana.py app/sources.py app/walletparse.py app/radar.py app/radar.js app/radar2.js app/server.py app/index.html "$HOST:$DIR/"
scp -q deploy/pump-graduated-web.service deploy/pump-graduated-analyze.service deploy/pump-graduated-analyze.timer deploy/pump-graduated-rules.service deploy/pump-graduated-rules.path deploy/pump-graduated-draft.service deploy/pump-graduated-draft.path deploy/pump-graduated-patterns.service deploy/pump-graduated-patterns.timer deploy/pump-graduated-patterns.path deploy/pump-graduated-holders.service deploy/pump-graduated-watch.service deploy/pump-graduated-dipwatch.service deploy/pump-graduated-monitor.service deploy/pump-graduated-jobs.service deploy/pump-graduated-trader.service "$HOST:/etc/systemd/system/"
ssh "$HOST" "systemctl daemon-reload && systemctl enable pump-graduated-web.service pump-graduated-analyze.timer pump-graduated-rules.path pump-graduated-draft.path pump-graduated-patterns.timer pump-graduated-patterns.path pump-graduated-holders.service pump-graduated-watch.service pump-graduated-dipwatch.service pump-graduated-monitor.service pump-graduated-jobs.service pump-graduated-trader.service >/dev/null 2>&1 && systemctl start pump-graduated-web.service pump-graduated-analyze.timer pump-graduated-rules.path pump-graduated-draft.path pump-graduated-patterns.timer pump-graduated-patterns.path && systemctl restart pump-graduated-holders.service && systemctl restart pump-graduated-watch.service && systemctl restart pump-graduated-dipwatch.service && systemctl restart pump-graduated-monitor.service && systemctl restart pump-graduated-jobs.service && systemctl restart pump-graduated-trader.service && systemctl restart pump-graduated-web.service && ufw allow 8090/tcp >/dev/null && systemctl is-active pump-graduated-web.service"
